-- Estudos ESE vindos da pasta compartilhada do OneDrive (ESE - ROTEIROS / ESE - Perguntas / ESE - Textos).
-- Cada roteiro guarda só os nomes dos arquivos; o link é montado no servidor com o compartilhamento da pasta
-- (variável ONEDRIVE_ESE_SHARE, fora do repositório). Nomes exatamente como estão no OneDrive.
-- Roteiro já cadastrado com o mesmo número (código "ROT. 14", "ROT 014"…) é atualizado no lugar, mantendo as escalas.

begin;

alter table app.studies
  add column if not exists onedrive jsonb check (onedrive is null or jsonb_typeof(onedrive) = 'object');

