),
folder as (
  select id from app.study_folders where department_key = 'doutrina' and parent_id is null and lower(title) = 'ese' limit 1
),
src as (
  select n, 'ROT. ' || lpad(n::text, 3, '0') as code, title, reference,
         jsonb_build_object('roteiro', 'ESE - ROTEIROS/' || roteiro, 'perguntas', 'ESE - Perguntas/' || perguntas, 'texto', 'ESE - Textos/' || texto) as files
    from data
),
updated as (
  update app.studies s
     set code = src.code, title = src.title, reference = src.reference, onedrive = src.files,
         folder_id = coalesce(s.folder_id, (select id from folder)), version = s.version + 1, updated_at = now()
    from src
   where s.department_key = 'doutrina' and s.study_type = 'ESE'
     and (regexp_match(coalesce(s.code, ''), '^\s*ROT\.?\s*0*(\d+)\s*$', 'i'))[1]::int = src.n
  returning src.n
)
insert into app.studies (department_key, folder_id, study_type, code, title, reference, onedrive)
select 'doutrina', (select id from folder), 'ESE', src.code, src.title, src.reference, src.files
  from src
 where src.n not in (select n from updated);

commit;
